// Data model for the Genesys point list (public/genesys-cards.json, regenerated by
// scripts/fetch-genesys-cards.mjs). Genesys is the format where every card on
// Konami's list costs points and a deck may spend at most GENESYS_BUDGET of them;
// any card missing from the list is free.

export const GENESYS_BUDGET = 100;

export type GenesysCardKind = 'monster' | 'spell' | 'trap';

export type GenesysMonsterClass = 'Normal' | 'Effect' | 'Ritual' | 'Fusion' | 'Synchro' | 'Xyz';

export type GenesysBanStatus = 'Forbidden' | 'Limited' | 'Semi-Limited';

export type GenesysCard = {
  id: number;
  name: string;
  points: number;
  kind: GenesysCardKind;
  /** Printed card type, e.g. "Xyz Effect Monster" / "Quick-Play Spell". */
  type: string;
  desc: string;

  // Monsters only.
  monsterClass?: GenesysMonsterClass;
  /** Monster type: Dragon, Spellcaster, ... */
  race?: string;
  attribute?: string;
  /** Level, or Rank for Xyz monsters. */
  level?: number;
  /** null for the "?" printed on a few cards. */
  atk?: number | null;
  def?: number | null;
  tuner?: boolean;
  extraDeck?: boolean;
  /** Typeline minus the monster type: Effect / Tuner / Spirit / Xyz / ... */
  traits?: string[];

  // Spells/Traps only: Normal, Quick-Play, Continuous, Field, Equip, Ritual, Counter.
  property?: string;

  archetype?: string;
  /** Current TCG limitation, when any. Genesys ignores it - Forbidden cards are
      playable here, they just cost the most points. */
  banTcg?: GenesysBanStatus;
};

export type GenesysCardList = {
  /** YYYY-MM-DD the list was pulled, shown in the view so a stale copy is obvious. */
  generatedAt: string;
  source: string;
  count: number;
  cards: GenesysCard[];
};

export const KIND_LABELS: Record<GenesysCardKind, string> = {
  monster: 'Monstruo',
  spell: 'Mágica',
  trap: 'Trampa',
};

export const MONSTER_CLASS_LABELS: Record<GenesysMonsterClass, string> = {
  Normal: 'Normal',
  Effect: 'Efecto',
  Ritual: 'Ritual',
  Fusion: 'Fusión',
  Synchro: 'Sincronía',
  Xyz: 'XYZ',
};

export const ATTRIBUTE_LABELS: Record<string, string> = {
  DARK: 'Oscuridad',
  LIGHT: 'Luz',
  EARTH: 'Tierra',
  WATER: 'Agua',
  FIRE: 'Fuego',
  WIND: 'Viento',
  DIVINE: 'Divino',
};

export const PROPERTY_LABELS: Record<string, string> = {
  Normal: 'Normal',
  'Quick-Play': 'Rápida',
  Continuous: 'Continua',
  Field: 'Campo',
  Equip: 'Equipo',
  Ritual: 'Ritual',
  Counter: 'Contraefecto',
};

export const BAN_LABELS: Record<GenesysBanStatus, string> = {
  Forbidden: 'Prohibida en TCG',
  Limited: 'Limitada en TCG',
  'Semi-Limited': 'Semi-limitada en TCG',
};

// Monster types keep their English names (how they're printed on TCG cards and
// how players search for them), so no label map for `race`.
